const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-121.18, 45.62]); // Dallasport, Washington
    const startDate = '2022-07-01';
    const endDate = '2022-07-31';

    // 2. Data Acquisition
    let collection = ee.ImageCollection('ECMWF/ERA5-LAND/DAILY_AGGR')
        .filterBounds(point)
        .filterDate(startDate, endDate)
        .select('temperature_2m_max');

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        console.log("Evidence: No ERA5-Land images found for the specified date and location.");
        console.log("C1");
        return;
    }
    console.log(`Evidence: Found ${collectionSize} daily images for July 2022.`);

    // 3. Processing: Find the maximum temperature over the month
    const maxTempImage = collection.max();

    // 4. Calculation: Extract the maximum temperature value at the point
    const scale = 1000; // Native resolution is ~11km, so 1000m is safe.
    const maxTempDict = maxTempImage.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: point,
        scale: scale,
        maxPixels: 1e9
    });

    const maxTempKelvin = maxTempDict.get('temperature_2m_max').getInfo();

    if (maxTempKelvin === null || typeof maxTempKelvin === 'undefined') {
        console.log("Evidence: Calculation failed, could not extract temperature value.");
        console.log("C3");
        return;
    }

    // 5. Validation & Final Answer
    // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
    const maxTempFahrenheit = (maxTempKelvin - 273.15) * 9 / 5 + 32;

    console.log(`Evidence: Max air temperature in Kelvin: ${maxTempKelvin.toFixed(2)} K`);
    console.log(`Evidence: Max air temperature in Fahrenheit: ${maxTempFahrenheit.toFixed(2)} °F`);

    if (maxTempFahrenheit >= 95) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
